+    }
+    let (mut ax, rho) = line(data, u, a_total)?;
+    let mut keep: Vec<bool> = Vec::new();
+    for _ in 0..LTS_ROUNDS {
+        let miss: Vec<Option<f64>> = data.iter().map(|d| dist(d, ax)).collect();
+        let next = lower_half(data, &miss)?;
+        if next == keep {
+            break;
+        }
+        let kept: Vec<Datum> = data
+            .iter()
+            .zip(&next)
