+/// too little of the answering area to place a line honestly.
+fn lower_half(data: &[Datum], miss: &[Option<f64>]) -> Option<Vec<bool>> {
+    let mut rows: Vec<(f64, f64)> = data.iter().zip(miss).filter_map(|(d, m)| m.map(|e| (e, d.a))).collect();
