+        return None;
+    }
+    rows.sort_by(|x, y| x.0.total_cmp(&y.0));
+    let (mut acc, mut med) = (0.0, f64::INFINITY);
+    for (e, a) in &rows {
+        acc += a;
+        if acc >= 0.5 * ans {
