+            break;
+        }
+    }
+    let next: Vec<bool> = miss.iter().map(|m| m.is_none_or(|e| e <= med)).collect();
+    let (mut a_kept, mut n_kept) = (0.0, 0usize);
+    for ((d, m), k) in data.iter().zip(miss).zip(&next) {
+        if *k && m.is_some() {
+            a_kept += d.a;
+            n_kept += 1;
+        }
+    }
