+fn fold(n: Point3) -> Point3 {
+    let (ax, ay, az) = (n.x.abs(), n.y.abs(), n.z.abs());
+    let big = if ax >= ay && ax >= az {
+        n.x
+    } else if ay >= az {
+        n.y
+    } else {
+        n.z
+    };
+    if big < 0.0 {
+        Point3::new(-n.x, -n.y, -n.z)
+    } else {
+        n
+    }
+}
